-- Новый тип ноды type_word («Напечатай слово»): ученик печатает слово на клавиатуре как на
-- iPhone, светятся только буквы слова и дополнительные буквы автора (extraLetters).
-- Легенда обменного JSON должна знать правила для этого типа: что писать в word и
-- extraLetters, пояснение перед нодой и почему ответы не повторяют слово. Таблиц и колонок
-- не меняем. Идемпотентно: вставка только если такого правила ещё нет.
insert into public.lesson_rules (rule_text, sort_order, category)
select
  'type_word («Напечатай слово») — ученик печатает ОДНО слово на клавиатуре как на iPhone: светятся (нажимаются) только буквы самого слова и extraLetters, остальные тусклые и мёртвые. word — одно слово или короткое из двух («ice cream»), без точки и без предложения (для целых фраз есть phrase_assembly/fill_blanks). extraLetters — 2–4 буквы-ловушки строкой, например "xzq": подбирай ПОХОЖЕЕ, где легко ошибиться (путают на слух или в написании: i/e, s/c), а не случайные буквы; буквы самого слова повторять не нужно. Перед КАЖДОЙ нодой type_word нужна короткая текстовая нода-пояснение — что напечатать и что печатать нужно тапами по светящимся буквам, простыми словами. Напечатанное слово ВСЕГДА уходит в чат пузырём справа (отдельной галочки нет), поэтому responseCorrect/responseWrong не повторяют его словами. После трёх неверных попыток слово раскрывается само — отдельную реплику-раскрытие не пиши. Триггеры: type_correct / type_wrong.',
  230,
  'principle'
where not exists (
  select 1 from public.lesson_rules
  where rule_text like 'type_word («Напечатай слово») — ученик печатает ОДНО слово на клавиатуре%'
);
